import { Component } from '@angular/core';
import { NFormStatic } from '@pebula/nform';

@Component({
  selector: 'app-basic-form',
  template: `<pbl-nform [model]="person"></pbl-nform>`
})
export class BasicFormComponent {
  person = {
    name: 'John Doe',
    email: 'john@example.com',
    age: 30
  };
}

import { Component } from '@angular/core';
import { NFormStatic } from '@pebula/nform';

@Component({
  selector: 'app-custom-template',
  template: `
    <pbl-nform [model]="user">
      <ng-template pblNFormOverride="email">
        <div>Custom Email Field: {{user.email}}</div>
      </ng-template>
    </pbl-nform>
  `
})
export class CustomTemplateComponent {
  user = {
    name: 'Jane Doe',
    email: 'jane@example.com'
  };
}

import { Component } from '@angular/core';
import { NFormStatic, NFormValidator } from '@pebula/nform';
import { Validators } from '@angular/forms';

@Component({
  selector: 'app-validation',
  template: `<pbl-nform [model]="data"></pbl-nform>`
})
export class ValidationComponent {
  @NFormValidator('email', Validators.email)
  @NFormValidator('name', Validators.required)
  data = {
    name: '',
    email: ''
  };
}

